CREATE OR ALTER PROCEDURE [dbo].[uspKpiMetricDefinition_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @EffectiveOn DATE = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[MetricCode]
			, t.[MetricName]
			, t.[DomainCode]
			, t.[UnitCode]
			, t.[FormulaDescription]
			, t.[AggregationCode]
			, t.[VersionNo]
			, t.[EffectiveFrom]
			, t.[EffectiveTo]
			, t.[IsActive]
			, t.[CreatedDate]
		FROM [dbo].[KpiMetricDefinition] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[MetricCode] LIKE CONCAT('%', @SearchText, '%') OR t.[MetricName] LIKE CONCAT('%', @SearchText, '%') OR t.[DomainCode] LIKE CONCAT('%', @SearchText, '%') OR t.[UnitCode] LIKE CONCAT('%', @SearchText, '%') OR t.[AggregationCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (@EffectiveOn IS NULL OR ((t.[EffectiveFrom] IS NULL OR t.[EffectiveFrom] <= @EffectiveOn) AND (t.[EffectiveTo] IS NULL OR t.[EffectiveTo] >= @EffectiveOn)))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'metricCode' THEN r.[MetricCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'metricCode' THEN r.[MetricCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'metricName' THEN r.[MetricName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'metricName' THEN r.[MetricName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'domainCode' THEN r.[DomainCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'domainCode' THEN r.[DomainCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'unitCode' THEN r.[UnitCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'unitCode' THEN r.[UnitCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'formulaDescription' THEN r.[FormulaDescription] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'formulaDescription' THEN r.[FormulaDescription] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'aggregationCode' THEN r.[AggregationCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'aggregationCode' THEN r.[AggregationCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'versionNo' THEN r.[VersionNo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'versionNo' THEN r.[VersionNo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'isActive' THEN r.[IsActive] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'isActive' THEN r.[IsActive] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
